//! Does the V2.4 path reproduce BirdNET-Pi?
//!
//! A BirdNET-Pi user who moves here with the same model and the same audio has
//! to see the same detections. This runs the shipping pipeline — decode, chunk,
//! the real ONNX V2.4 classifier, the sensitivity-scaled sigmoid, the
//! confidence threshold — over `tests/testdata/Pica_pica_30s.wav` at
//! BirdNET-Pi's own defaults and diffs the result against what BirdNET-Pi's
//! unmodified code produced for the same recording (`tools/parity/`, golden
//! `a1_station.json`, regenerated by `tools/parity/regenerate.sh`).
//!
//! Two independent anchors:
//!
//! * the three confidences BirdNET-Pi asserts for this recording in its own
//!   `analysis.py` (`0.912, 0.9316, 0.8857`), and
//! * its per-chunk top-10 for all ten 3-second windows.
//!
//! The model under test is birdnet-go's published FP32 V2.4 ONNX
//! (`tphakala/BirdNET-v2.4`), BirdNET-Pi runs the FP16 TFLite build of the same
//! network, so scores agree to a few thousandths rather than bit for bit:
//! `TOL_CONF` and `TOL_LOGIT` are set from the measured gap with headroom, not
//! to hide one.
//!
//! Skipped unless `BIRDNET_TEST_V24_MODEL` and `BIRDNET_TEST_V24_LABELS` name a
//! V2.4 ONNX and its labels; CI sets `BIRDNET_REQUIRE_V24_MODEL=1` once it has
//! fetched and verified them, which turns a skip into a failure.

mod common;

use std::path::Path;

use birdnet_core::config::DEFAULT_SENSITIVITY;
use birdnet_core::detection::pipeline::{PipelineConfig, process_file};
use birdnet_core::inference::labels::LabelSet;
use birdnet_core::inference::model::{BirdNetModel, ModelConfig, logit_slope};

const WAV: &str = "tests/testdata/Pica_pica_30s.wav";
const GOLDEN: &str = "tools/parity/golden/matrix/a1_station.json";

/// BirdNET-Pi's own expected confidences for the recording's three magpie
/// windows (3, 12 and 21 s), `scripts/utils/analysis.py` `__main__`.
const PI_EXPECTED: [(f32, f32); 3] = [(3.0, 0.912), (12.0, 0.9316), (21.0, 0.8857)];

/// Largest confidence gap tolerated against BirdNET-Pi's rounded values.
/// Measured: 3e-4, 2e-4, 7e-4 (FP32 ONNX against FP16 TFLite weights).
const TOL_CONF: f32 = 2e-3;

/// Largest raw-logit gap tolerated on labels both sides report. Measured on
/// this recording: 0.077.
const TOL_LOGIT: f64 = 0.15;

/// BirdNET-Pi's confidence threshold default (`install_config.sh`).
const PI_CONFIDENCE: f32 = 0.7;

#[test]
fn v24_reproduces_birdnet_pi_on_the_magpie_recording() {
    let Some((model_path, labels_path)) = common::v24_model_paths() else {
        return;
    };
    // The test is only meaningful at the default sensitivity BirdNET-Pi ships.
    assert!((DEFAULT_SENSITIVITY - 1.25).abs() < f32::EPSILON);
    let slope = f64::from(logit_slope(DEFAULT_SENSITIVITY));
    assert!((slope - 0.75).abs() < 1e-9, "BirdNET-Pi's default slope");

    let labels = LabelSet::load(&labels_path).expect("labels");
    let mut model = BirdNetModel::load(
        &model_path,
        labels,
        ModelConfig {
            sensitivity: DEFAULT_SENSITIVITY,
            confidence_threshold: 0.0,
            top_n: 10,
            num_threads: 2,
        },
    )
    .expect("model");
    assert!(
        !model.is_probability_output(),
        "a V2.4 model emits logits; this is not one"
    );

    let dir = tempfile::tempdir().expect("tempdir");
    let staged = dir.path().join("2026-06-15-birdnet-10:00:00.wav");
    std::fs::copy(WAV, &staged).expect("stage the recording");
    let cfg = PipelineConfig {
        target_sample_rate: model.infer_sample_rate(),
        raw_audio_input: model.expects_raw_audio(),
        chunk_duration_secs: model.recommended_chunk_secs(),
        confidence_threshold: 0.0,
        ..PipelineConfig::default()
    };
    let chunks = process_file(&staged, &cfg).expect("pipeline");

    let golden: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(GOLDEN).expect("golden")).expect("json");
    let run = golden["runs"]
        .as_array()
        .expect("runs")
        .iter()
        .find(|r| r["clip"]["file"] == "pica_pica_30s.wav")
        .expect("the golden has the Pica clip");
    let pi_chunks = run["chunks"].as_array().expect("chunks");
    assert_eq!(chunks.len(), pi_chunks.len(), "chunk count");

    let mut stored: Vec<(f32, String, f32)> = Vec::new();
    for (chunk, pi) in chunks.iter().zip(pi_chunks) {
        let pred = model
            .predict_chunk(
                &chunk.spectrogram.data,
                "2026-06-15",
                "10:00:00",
                chunk.start_secs,
                chunk.end_secs,
                23,
            )
            .expect("inference");
        let start = chunk.start_secs;
        assert!(
            (f64::from(start) - pi["start"].as_f64().unwrap()).abs() < 1e-3,
            "chunk start {start}"
        );

        // Same top species as BirdNET-Pi's.
        let pi_top10: Vec<(&str, f64)> = pi["top10"]
            .as_array()
            .unwrap()
            .iter()
            .zip(pi["top10_logits"].as_array().unwrap())
            .map(|(e, l)| (e[0].as_str().unwrap(), l.as_f64().unwrap()))
            .collect();
        assert_eq!(
            pred.detections[0].scientific_name, pi_top10[0].0,
            "top-1 at {start} s"
        );

        // Raw logits recovered from the confidence (`conf = sigmoid(slope * logit)`).
        for d in &pred.detections {
            let Some((_, pi_logit)) = pi_top10.iter().find(|(n, _)| *n == d.scientific_name) else {
                continue;
            };
            let p = f64::from(d.confidence);
            let ours = (p / (1.0 - p)).ln() / slope;
            assert!(
                (ours - pi_logit).abs() < TOL_LOGIT,
                "{} at {start} s: logit {ours:.4} vs BirdNET-Pi {pi_logit:.4}",
                d.scientific_name
            );
        }

        for d in pred
            .detections
            .iter()
            .filter(|d| d.confidence >= PI_CONFIDENCE)
        {
            stored.push((start, d.scientific_name.clone(), d.confidence));
        }
    }

    // What BirdNET-Pi stores at its defaults, before its occurrence filter:
    // exactly the three magpie windows, and nothing else.
    assert_eq!(
        stored.len(),
        PI_EXPECTED.len(),
        "detections at confidence >= {PI_CONFIDENCE}: {stored:?}"
    );
    for ((start, name, conf), (pi_start, pi_conf)) in stored.iter().zip(PI_EXPECTED) {
        assert_eq!(name, "Pica pica");
        assert!(
            (start - pi_start).abs() < 1e-3,
            "window {start} vs {pi_start}"
        );
        assert!(
            (conf - pi_conf).abs() < TOL_CONF,
            "{start} s: {conf} vs BirdNET-Pi {pi_conf}"
        );
    }
    assert!(Path::new(WAV).exists());
}
